fn array_split(a: Vec<i32>) -> (Vec<i32>, Vec<i32>) {
    let len = a.len();
    
    if len == 0 {
        // Case for empty input
        return (Vec::new(), Vec::new());
    } else if len == 1 {
        // Case for single element
        return (Vec::new(), a);
    } else {
        // Case for length greater than 1
        let first = vec![a[0]]; // Take the first element
        let second = a[1..].to_vec(); // Take the rest of the elements
        return (first, second);
    }
}